SELECT MAX(signal_date)
FROM quant_core_signal
WHERE model_code = #{modelCode}

SELECT 
FROM quant_core_signal
WHERE model_code = #{modelCode}
  AND signal_date = #{signalDate}
ORDER BY rank ASC NULLS LAST, score DESC, asset_code
LIMIT #{limit}

SELECT 
FROM quant_core_signal
WHERE model_code = #{modelCode}
  AND asset_code = #{assetCode}
  AND signal_date <= #{signalDate}
ORDER BY signal_date DESC
LIMIT #{limit}

SELECT COUNT(*)
FROM quant_trade_log
WHERE strategy_id = #{strategyId}
